"""A2 acceptance preparation uses generated bytes and API doubles only."""
import contextlib
import importlib.util
import io
import json
import tempfile
import unittest
from pathlib import Path
from types import SimpleNamespace
from unittest.mock import patch

from hashbrown_ir import acquisition as acq
from hashbrown_ir.endpoint import bind
from hashbrown_ir.lab_images import disk_fixture, memory_fixture
from hashbrown_ir.storage import CaseError, create, save
from test_acquisition import API, CLIENT

_spec = importlib.util.spec_from_file_location("a2_lab", Path(__file__).parents[1] / "scripts" / "a2_lab.py")
a2 = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(a2)


class A2LabTests(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory(prefix="hashbrown-a2-test-")
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name).resolve()
        self.case = create(self.root / "cases", "LAB", "Lab analyst")
        bind(self.case, CLIENT, "lab-win01")
        self.bundle = self.root / "acceptance"
        self.bundle.mkdir()
        self.source = self.root / "disk.img"
        self.source.write_bytes(disk_fixture())
        self.job = acq.import_image(self.case, CLIENT, "disk", self.source, "Lab analyst", simulation=True)

    def image_snapshot(self, scope="fixture-transfer"):
        return a2.snapshot(self.root / "cases", self.case.id, self.job["id"],
                           self.case.path / self.job["content_path"], scope, 2 * acq.CHUNK)

    def record(self, value):
        path = self.bundle / "run.json"
        save(path, value)
        return path

    def test_template_does_not_infer_a_workstation_target(self):
        value = a2.template()
        self.assertTrue(all(v is None for v in value["target"].values()))
        self.assertIsNone(value["authorization_reference"])
        result = a2.assess(self.record(value))
        self.assertEqual(result["status"], "incomplete")
        self.assertEqual(result["native_capture"], {"disk": "not_executed", "memory": "not_executed"})

    def test_fixture_snapshot_verifies_bytes_without_native_qualification_or_case_writes(self):
        before = {str(p): (p.read_bytes(), p.stat().st_mtime_ns) for p in self.case.path.rglob("*") if p.is_file()}
        with patch("hashbrown_ir.endpoint.Velociraptor", side_effect=AssertionError("no API")):
            result = self.image_snapshot("designated-vm")
        self.assertEqual(result["byte_integrity"], "verified")
        self.assertEqual(result["native_capture"], "not_executed")
        self.assertEqual(result["independent_readability"], "not_assessed")
        self.assertEqual(result["image"]["bytes"], 1474560)
        self.assertEqual(before, {str(p): (p.read_bytes(), p.stat().st_mtime_ns) for p in self.case.path.rglob("*") if p.is_file()})

    def test_snapshot_rejects_wrong_image_and_tampering_does_not_verify(self):
        other = self.root / "other.img"
        other.write_bytes(self.source.read_bytes())
        with self.assertRaisesRegex(CaseError, "saved job"):
            a2.snapshot(self.root / "cases", self.case.id, self.job["id"], other, "fixture-transfer", 2 * acq.CHUNK)
        image = self.case.path / self.job["content_path"]
        with image.open("r+b") as stream:
            stream.write(b"changed")
        self.assertEqual(self.image_snapshot()["byte_integrity"], "not_verified_complete")

    def test_bounded_input_refuses_device_paths_and_oversized_files(self):
        with self.assertRaises(CaseError):
            a2.fingerprint(r"\\.\PhysicalDrive0")
        with self.assertRaises(CaseError):
            a2.fingerprint(self.source, 16)

    def test_output_receipts_are_not_overwritten(self):
        path = self.bundle / "receipt.json"
        a2.write_new(path, {"a": 1})
        before = path.read_bytes()
        with self.assertRaises(CaseError):
            a2.write_new(path, {"a": 2})
        self.assertEqual(path.read_bytes(), before)

    def test_operator_claims_and_fixture_hash_cannot_pass_native_readability(self):
        snap = self.image_snapshot()
        a2.write_new(self.bundle / "disk.json", snap)
        value = a2.template()
        value.update(authorization_reference="Operator says all tests passed", native_capture="passed", independent_readability="passed")
        value["target"] = dict(client_id=CLIENT, hostname="lab-win01", org_id="root", disk_number=0)
        value["snapshots"]["disk"] = "disk.json"
        result = a2.assess(self.record(value))
        self.assertEqual(result["qualification"], "not_granted")
        self.assertEqual(result["byte_integrity"]["disk"], "snapshot_reports_verified")
        self.assertEqual(result["native_capture"]["disk"], "not_executed")
        self.assertEqual(result["independent_readability"]["disk"], "not_executed")

    def test_reader_receipt_requires_retained_original_output_and_valid_hash(self):
        output = self.bundle / "reader-output.txt"
        output.write_text("Reader stdout and exact command; fixture only", encoding="utf-8")
        receipt = dict(schema=1, type="hashbrown-a2-fingerprint", role="reader-output", file=a2.fingerprint(output))
        a2.write_new(self.bundle / "reader.json", receipt)
        value = a2.template()
        value["readers"]["disk"]["output"] = "reader.json"
        result = a2.assess(self.record(value))
        self.assertEqual(result["independent_readability"]["disk"], "output_present_review_required")
        self.assertEqual(result["qualification"], "not_granted")
        output.write_text("altered", encoding="utf-8")
        with self.assertRaisesRegex(CaseError, "differs"):
            a2.assess(self.bundle / "run.json")

    def test_evidence_paths_cannot_escape_bundle(self):
        value = a2.template()
        value["snapshots"]["disk"] = "../outside.json"
        with self.assertRaisesRegex(CaseError, "relative"):
            a2.assess(self.record(value))

    def remote_job(self):
        api = API(memory_fixture())
        job = acq.start(self.case, CLIENT, "memory", api, "Lab analyst", source="C:\\Lab\\memory.raw", simulation=True)
        exe, config = self.bundle / "inert-runtime.exe", self.bundle / "dummy-api.yaml"
        exe.write_bytes(b"inert; must never execute")
        config.write_bytes(b"test-only dummy config")
        args = SimpleNamespace(root=self.root / "cases", case_id=self.case.id, job=job["id"], client_id=CLIENT,
                               hostname="lab-win01", org="root", velociraptor=exe, api_config=config,
                               download_api_config=None, transfer_bytes=acq.CHUNK, seconds=120)
        return api, job, args

    def test_checkpoint_wrong_target_never_constructs_api(self):
        _, _, args = self.remote_job()
        args.hostname = "wrong-host"
        with patch.object(a2, "Velociraptor", side_effect=AssertionError("must not contact API")):
            with self.assertRaisesRegex(CaseError, "Explicit target"):
                a2.sync_checkpoint(args)

    def test_bounded_checkpoint_and_resume_reuse_same_flow_without_collection(self):
        api, job, args = self.remote_job()
        bounded = a2.BoundedAPI(api, a2.time.monotonic() + 120, 0, acq.CHUNK)
        with self.assertRaisesRegex(CaseError, "no collection"):
            bounded.query("SELECT collect_client() FROM scope()")
        with (patch.object(a2, "Velociraptor", return_value=api),
              patch.object(acq, "start", side_effect=AssertionError("no new collection"))):
            result = a2.sync_checkpoint(args)
        self.assertTrue(result["controlled_stop"])
        self.assertTrue(result["interrupted_transfer_observed"])
        self.assertEqual(result["after_offset"], acq.CHUNK)
        self.assertEqual(result["submitted_collections"], 0)
        completed = acq.resume(self.case, job["id"], api)
        self.assertEqual(completed["flow_id"], result["flow_id"])
        self.assertEqual(completed["status"], "verified")
        self.assertEqual(api.starts, 1)

    def test_too_short_image_does_not_claim_interruption(self):
        api, _, args = self.remote_job()
        api.data = b"short synthetic bytes"
        with patch.object(a2, "Velociraptor", return_value=api):
            result = a2.sync_checkpoint(args)
        self.assertFalse(result["interrupted_transfer_observed"])
        self.assertEqual(result["status"], "verified")

    def test_cli_template_and_assess_are_local_and_explicitly_incomplete(self):
        output = io.StringIO()
        with contextlib.redirect_stdout(output), patch.object(a2, "Velociraptor", side_effect=AssertionError("no API")):
            self.assertEqual(a2.main(["template", "--output", str(self.bundle / "run.json")]), 0)
            self.assertEqual(a2.main(["assess", "--record", str(self.bundle / "run.json"), "--output", str(self.bundle / "assessment.json")]), 2)
        result = json.loads((self.bundle / "assessment.json").read_text())
        self.assertEqual(result["qualification"], "not_granted")

    def test_snapshot_and_sync_outputs_inside_case_root_are_rejected_before_work(self):
        common = ["--root", str(self.root / "cases"), "--case-id", self.case.id,
                  "--job", self.job["id"], "--output", str(self.case.path / "must-not-exist.json")]
        commands = [["snapshot", *common, "--image", str(self.case.path / self.job["content_path"]), "--scope", "fixture-transfer"],
                    ["sync-checkpoint", *common, "--client-id", CLIENT, "--hostname", "lab-win01", "--org", "root",
                     "--velociraptor", "unused.exe", "--api-config", "unused.yaml"]]
        for args in commands:
            with (self.subTest(command=args[0]), contextlib.redirect_stderr(io.StringIO()),
                  patch.object(a2, "fingerprint", side_effect=AssertionError("must reject before hashing")),
                  patch.object(a2, "Velociraptor", side_effect=AssertionError("must reject before API"))):
                self.assertEqual(a2.main(args), 1)
            self.assertFalse((self.case.path / "must-not-exist.json").exists())


if __name__ == "__main__":
    unittest.main()
